561|int mz_uncompress2(unsigned char *pDest, mz_ulong *pDest_len, const unsigned char *pSource, mz_ulong *pSource_len)
562|{
563|    mz_stream stream;
564|    int status;
565|    memset(&stream, 0, sizeof(stream));
566|
567|    /* In case mz_ulong is 64-bits (argh I hate longs). */
568|    if ((mz_uint64)(*pSource_len | *pDest_len) > 0xFFFFFFFFU)
569|        return MZ_PARAM_ERROR;
570|
571|    stream.next_in = pSource;
572|    stream.avail_in = (mz_uint32)*pSource_len;
573|    stream.next_out = pDest;
574|    stream.avail_out = (mz_uint32)*pDest_len;
575|
576|    status = mz_inflateInit(&stream);
577|    if (status != MZ_OK)
578|        return status;
579|
580|    status = mz_inflate(&stream, MZ_FINISH);
581|    *pSource_len = *pSource_len - stream.avail_in;
582|    if (status != MZ_STREAM_END)
583|    {
584|        mz_inflateEnd(&stream);
585|        return ((status == MZ_BUF_ERROR) && (!stream.avail_in)) ? MZ_DATA_ERROR : status;
586|    }
587|    *pDest_len = stream.total_out;
588|
589|    return mz_inflateEnd(&stream);
590|}

371|int mz_inflateInit2(mz_streamp pStream, int window_bits)
372|{
373|    inflate_state *pDecomp;
374|    if (!pStream)
375|        return MZ_STREAM_ERROR;
376|    if ((window_bits != MZ_DEFAULT_WINDOW_BITS) && (-window_bits != MZ_DEFAULT_WINDOW_BITS))
377|        return MZ_PARAM_ERROR;
378|
379|    pStream->data_type = 0;
380|    pStream->adler = 0;
381|    pStream->msg = NULL;
382|    pStream->total_in = 0;
383|    pStream->total_out = 0;
384|    pStream->reserved = 0;
385|    if (!pStream->zalloc)
386|        pStream->zalloc = miniz_def_alloc_func;
387|    if (!pStream->zfree)
388|        pStream->zfree = miniz_def_free_func;
389|
390|    pDecomp = (inflate_state *)pStream->zalloc(pStream->opaque, 1, sizeof(inflate_state));
391|    if (!pDecomp)
392|        return MZ_MEM_ERROR;
393|
394|    pStream->state = (struct mz_internal_state *)pDecomp;
395|
396|    tinfl_init(&pDecomp->m_decomp);
397|    pDecomp->m_dict_ofs = 0;
398|    pDecomp->m_dict_avail = 0;
399|    pDecomp->m_last_status = TINFL_STATUS_NEEDS_MORE_INPUT;
400|    pDecomp->m_first_call = 1;
401|    pDecomp->m_has_flushed = 0;
402|    pDecomp->m_window_bits = window_bits;
403|
404|    return MZ_OK;
