438|int mz_inflate(mz_streamp pStream, int flush)
439|{
440|    inflate_state *pState;
441|    mz_uint n, first_call, decomp_flags = TINFL_FLAG_COMPUTE_ADLER32;
442|    size_t in_bytes, out_bytes, orig_avail_in;
443|    tinfl_status status;
444|
445|    if ((!pStream) || (!pStream->state))
446|        return MZ_STREAM_ERROR;
447|    if (flush == MZ_PARTIAL_FLUSH)
448|        flush = MZ_SYNC_FLUSH;
449|    if ((flush) && (flush != MZ_SYNC_FLUSH) && (flush != MZ_FINISH))
450|        return MZ_STREAM_ERROR;
451|
452|    pState = (inflate_state *)pStream->state;
453|    if (pState->m_window_bits > 0)
454|        decomp_flags |= TINFL_FLAG_PARSE_ZLIB_HEADER;
455|    orig_avail_in = pStream->avail_in;
456|
457|    first_call = pState->m_first_call;
458|    pState->m_first_call = 0;
459|    if (pState->m_last_status < 0)
460|        return MZ_DATA_ERROR;
461|
462|    if (pState->m_has_flushed && (flush != MZ_FINISH))
463|        return MZ_STREAM_ERROR;
464|    pState->m_has_flushed |= (flush == MZ_FINISH);
465|
466|    if ((flush == MZ_FINISH) && (first_call))
467|    {
468|        /* MZ_FINISH on the first call implies that the input and output buffers are large enough to hold the entire compressed/decompressed file. */
469|        decomp_flags |= TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF;
470|        in_bytes = pStream->avail_in;
471|        out_bytes = pStream->avail_out;
472|        status = tinfl_decompress(&pState->m_decomp, pStream->next_in, &in_bytes, pStream->next_out, pStream->next_out, &out_bytes, decomp_flags);
473|        pState->m_last_status = status;
474|        pStream->next_in += (mz_uint)in_bytes;
475|        pStream->avail_in -= (mz_uint)in_bytes;
476|        pStream->total_in += (mz_uint)in_bytes;
477|        pStream->adler = tinfl_get_adler32(&pState->m_decomp);
478|        pStream->next_out += (mz_uint)out_bytes;
479|        pStream->avail_out -= (mz_uint)out_bytes;
480|        pStream->total_out += (mz_uint)out_bytes;
481|
482|        if (status < 0)
483|            return MZ_DATA_ERROR;
484|        else if (status != TINFL_STATUS_DONE)
485|        {
486|            pState->m_last_status = TINFL_STATUS_FAILED;
487|            return MZ_BUF_ERROR;
488|        }
489|        return MZ_STREAM_END;
490|    }
491|    /* flush != MZ_FINISH then we must assume there's more input. */
492|    if (flush != MZ_FINISH)
493|        decomp_flags |= TINFL_FLAG_HAS_MORE_INPUT;
494|
495|    if (pState->m_dict_avail)
496|    {
497|        n = MZ_MIN(pState->m_dict_avail, pStream->avail_out);
498|        memcpy(pStream->next_out, pState->m_dict + pState->m_dict_ofs, n);
499|        pStream->next_out += n;
500|        pStream->avail_out -= n;
501|        pStream->total_out += n;
502|        pState->m_dict_avail -= n;
503|        pState->m_dict_ofs = (pState->m_dict_ofs + n) & (TINFL_LZ_DICT_SIZE - 1);
504|        return ((pState->m_last_status == TINFL_STATUS_DONE) && (!pState->m_dict_avail)) ? MZ_STREAM_END : MZ_OK;
505|    }
506|
507|    for (;;)
508|    {
509|        in_bytes = pStream->avail_in;
510|        out_bytes = TINFL_LZ_DICT_SIZE - pState->m_dict_ofs;
511|
512|        status = tinfl_decompress(&pState->m_decomp, pStream->next_in, &in_bytes, pState->m_dict, pState->m_dict + pState->m_dict_ofs, &out_bytes, decomp_flags);
513|        pState->m_last_status = status;
514|
515|        pStream->next_in += (mz_uint)in_bytes;
516|        pStream->avail_in -= (mz_uint)in_bytes;
517|        pStream->total_in += (mz_uint)in_bytes;
518|        pStream->adler = tinfl_get_adler32(&pState->m_decomp);
519|
520|        pState->m_dict_avail = (mz_uint)out_bytes;
521|
522|        n = MZ_MIN(pState->m_dict_avail, pStream->avail_out);
523|        memcpy(pStream->next_out, pState->m_dict + pState->m_dict_ofs, n);
524|        pStream->next_out += n;
525|        pStream->avail_out -= n;
526|        pStream->total_out += n;
527|        pState->m_dict_avail -= n;
528|        pState->m_dict_ofs = (pState->m_dict_ofs + n) & (TINFL_LZ_DICT_SIZE - 1);
529|
530|        if (status < 0)
531|            return MZ_DATA_ERROR; /* Stream is corrupted (there could be some uncompressed data left in the output dictionary - oh well). */
532|        else if ((status == TINFL_STATUS_NEEDS_MORE_INPUT) && (!orig_avail_in))
533|            return MZ_BUF_ERROR; /* Signal caller that we can't make forward progress without supplying more input or by setting flush to MZ_FINISH. */
534|        else if (flush == MZ_FINISH)
535|        {
536|            /* The output buffer MUST be large to hold the remaining uncompressed data when flush==MZ_FINISH. */
537|            if (status == TINFL_STATUS_DONE)
538|                return pState->m_dict_avail ? MZ_BUF_ERROR : MZ_STREAM_END;
539|            /* status here must be TINFL_STATUS_HAS_MORE_OUTPUT, which means there's at least 1 more byte on the way. If there's no more room left in the output buffer then something is wrong. */
540|            else if (!pStream->avail_out)
541|                return MZ_BUF_ERROR;
542|        }
543|        else if ((status == TINFL_STATUS_DONE) || (!pStream->avail_in) || (!pStream->avail_out) || (pState->m_dict_avail))
544|            break;
545|    }
546|
547|    return ((status == TINFL_STATUS_DONE) && (!pState->m_dict_avail)) ? MZ_STREAM_END : MZ_OK;
548|}
