673|void *tinfl_decompress_mem_to_heap(const void *pSrc_buf, size_t src_buf_len, size_t *pOut_len, int flags)
674|{
675|    tinfl_decompressor decomp;
676|    void *pBuf = NULL, *pNew_buf;
677|    size_t src_buf_ofs = 0, out_buf_capacity = 0;
678|    *pOut_len = 0;
679|    tinfl_init(&decomp);
680|    for (;;)
681|    {
682|        size_t src_buf_size = src_buf_len - src_buf_ofs, dst_buf_size = out_buf_capacity - *pOut_len, new_out_buf_capacity;
683|        tinfl_status status = tinfl_decompress(&decomp, (const mz_uint8 *)pSrc_buf + src_buf_ofs, &src_buf_size, (mz_uint8 *)pBuf, pBuf ? (mz_uint8 *)pBuf + *pOut_len : NULL, &dst_buf_size,
684|                                               (flags & ~TINFL_FLAG_HAS_MORE_INPUT) | TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF);
685|        if ((status < 0) || (status == TINFL_STATUS_NEEDS_MORE_INPUT))
686|        {
687|            MZ_FREE(pBuf);
688|            *pOut_len = 0;
689|            return NULL;
690|        }
691|        src_buf_ofs += src_buf_size;
692|        *pOut_len += dst_buf_size;
693|        if (status == TINFL_STATUS_DONE)
694|            break;
695|        new_out_buf_capacity = out_buf_capacity * 2;
696|        if (new_out_buf_capacity < 128)
697|            new_out_buf_capacity = 128;
698|        pNew_buf = MZ_REALLOC(pBuf, new_out_buf_capacity);
699|        if (!pNew_buf)
700|        {
701|            MZ_FREE(pBuf);
702|            *pOut_len = 0;
703|            return NULL;
704|        }
705|        pBuf = pNew_buf;
706|        out_buf_capacity = new_out_buf_capacity;
707|    }
