105|static tdefl_sym_freq *tdefl_radix_sort_syms(mz_uint num_syms, tdefl_sym_freq *pSyms0, tdefl_sym_freq *pSyms1)
106|{
107|    mz_uint32 total_passes = 2, pass_shift, pass, i, hist[256 * 2];
108|    tdefl_sym_freq *pCur_syms = pSyms0, *pNew_syms = pSyms1;
109|    MZ_CLEAR_ARR(hist);
110|    for (i = 0; i < num_syms; i++)
111|    {
112|        mz_uint freq = pSyms0[i].m_key;
113|        hist[freq & 0xFF]++;
114|        hist[256 + ((freq >> 8) & 0xFF)]++;
115|    }
116|    while ((total_passes > 1) && (num_syms == hist[(total_passes - 1) * 256]))
117|        total_passes--;
118|    for (pass_shift = 0, pass = 0; pass < total_passes; pass++, pass_shift += 8)
119|    {
120|        const mz_uint32 *pHist = &hist[pass << 8];
121|        mz_uint offsets[256], cur_ofs = 0;
122|        for (i = 0; i < 256; i++)
123|        {
124|            offsets[i] = cur_ofs;
125|            cur_ofs += pHist[i];
126|        }
127|        for (i = 0; i < num_syms; i++)
128|            pNew_syms[offsets[(pCur_syms[i].m_key >> pass_shift) & 0xFF]++] = pCur_syms[i];
129|        {
130|            tdefl_sym_freq *t = pCur_syms;
131|            pCur_syms = pNew_syms;
132|            pNew_syms = t;
133|        }
134|    }
135|    return pCur_syms;
136|}

223|static void tdefl_optimize_huffman_table(tdefl_compressor *d, int table_num, int table_len, int code_size_limit, int static_table)
224|{
225|    int i, j, l, num_codes[1 + TDEFL_MAX_SUPPORTED_HUFF_CODESIZE];
226|    mz_uint next_code[TDEFL_MAX_SUPPORTED_HUFF_CODESIZE + 1];
227|    MZ_CLEAR_ARR(num_codes);
228|    if (static_table)
229|    {
230|        for (i = 0; i < table_len; i++)
231|            num_codes[d->m_huff_code_sizes[table_num][i]]++;
232|    }
233|    else
234|    {
235|        tdefl_sym_freq syms0[TDEFL_MAX_HUFF_SYMBOLS], syms1[TDEFL_MAX_HUFF_SYMBOLS], *pSyms;
236|        int num_used_syms = 0;
237|        const mz_uint16 *pSym_count = &d->m_huff_count[table_num][0];
238|        for (i = 0; i < table_len; i++)
239|            if (pSym_count[i])
240|            {
241|                syms0[num_used_syms].m_key = (mz_uint16)pSym_count[i];
242|                syms0[num_used_syms++].m_sym_index = (mz_uint16)i;
243|            }
244|
245|        pSyms = tdefl_radix_sort_syms(num_used_syms, syms0, syms1);
246|        tdefl_calculate_minimum_redundancy(pSyms, num_used_syms);
247|
248|        for (i = 0; i < num_used_syms; i++)
249|            num_codes[pSyms[i].m_key]++;
250|
251|        tdefl_huffman_enforce_max_code_size(num_codes, num_used_syms, code_size_limit);
252|
253|        MZ_CLEAR_ARR(d->m_huff_code_sizes[table_num]);
254|        MZ_CLEAR_ARR(d->m_huff_codes[table_num]);
255|        for (i = 1, j = num_used_syms; i <= code_size_limit; i++)
256|            for (l = num_codes[i]; l > 0; l--)
257|                d->m_huff_code_sizes[table_num][pSyms[--j].m_sym_index] = (mz_uint8)(i);
258|    }
259|
260|    next_code[1] = 0;
261|    for (j = 0, i = 2; i <= code_size_limit; i++)
262|        next_code[i] = j = ((j + num_codes[i - 1]) << 1);
263|
264|    for (i = 0; i < table_len; i++)
265|    {
266|        mz_uint rev_code = 0, code, code_size;
267|        if ((code_size = d->m_huff_code_sizes[table_num][i]) == 0)
268|            continue;
269|        code = next_code[code_size]++;
270|        for (l = code_size; l > 0; l--, code >>= 1)
271|            rev_code = (rev_code << 1) | (code & 1);
272|        d->m_huff_codes[table_num][i] = (mz_uint16)rev_code;
273|    }
