360|    memcpy(code_sizes_to_pack, &d->m_huff_code_sizes[0][0], num_lit_codes);
361|    memcpy(code_sizes_to_pack + num_lit_codes, &d->m_huff_code_sizes[1][0], num_dist_codes);
362|    total_code_sizes_to_pack = num_lit_codes + num_dist_codes;
363|    num_packed_code_sizes = 0;
364|    rle_z_count = 0;
365|    rle_repeat_count = 0;
366|
367|    memset(&d->m_huff_count[2][0], 0, sizeof(d->m_huff_count[2][0]) * TDEFL_MAX_HUFF_SYMBOLS_2);
368|    for (i = 0; i < total_code_sizes_to_pack; i++)
369|    {
370|        mz_uint8 code_size = code_sizes_to_pack[i];
371|        if (!code_size)
372|        {
373|            TDEFL_RLE_PREV_CODE_SIZE();
374|            if (++rle_z_count == 138)
375|            {
376|                TDEFL_RLE_ZERO_CODE_SIZE();
377|            }
378|        }
379|        else
380|        {
381|            TDEFL_RLE_ZERO_CODE_SIZE();
382|            if (code_size != prev_code_size)
383|            {
384|                TDEFL_RLE_PREV_CODE_SIZE();
385|                d->m_huff_count[2][code_size] = (mz_uint16)(d->m_huff_count[2][code_size] + 1);
386|                packed_code_sizes[num_packed_code_sizes++] = code_size;
387|            }
388|            else if (++rle_repeat_count == 6)
389|            {
390|                TDEFL_RLE_PREV_CODE_SIZE();
391|            }
392|        }
393|        prev_code_size = code_size;
394|    }
395|    if (rle_repeat_count)
396|    {
397|        TDEFL_RLE_PREV_CODE_SIZE();
398|    }
399|    else
400|    {
401|        TDEFL_RLE_ZERO_CODE_SIZE();
402|    }
403|
404|    tdefl_optimize_huffman_table(d, 2, TDEFL_MAX_HUFF_SYMBOLS_2, 7, MZ_FALSE);
