406|    TDEFL_PUT_BITS(2, 2);
407|
408|    TDEFL_PUT_BITS(num_lit_codes - 257, 5);
409|    TDEFL_PUT_BITS(num_dist_codes - 1, 5);
410|
411|    for (num_bit_lengths = 18; num_bit_lengths >= 0; num_bit_lengths--)
