414|    num_bit_lengths = MZ_MAX(4, (num_bit_lengths + 1));
415|    TDEFL_PUT_BITS(num_bit_lengths - 4, 4);
416|    for (i = 0; (int)i < num_bit_lengths; i++)
417|        TDEFL_PUT_BITS(d->m_huff_code_sizes[2][s_tdefl_packed_code_size_syms_swizzle[i]], 3);
